inline bool active(DiagramTextItem *text){if(!text||!text->diagram()||!text->diagram()->project())return false;auto data=text->diagram()->project()->languageData();return QetLanguages16::activeLanguage(data)!=QetLanguages16::sourceLanguage(data)&&QetLanguages16::entry(data,text->languageId16()).value("enabled").toBool();}
inline void editText(DiagramTextItem *text,QWidget *parent=nullptr){
 if(!active(text)||text->diagram()->isReadOnly())return;auto *project=text->diagram()->project();auto before=project->languageData();auto beforePos=QetLanguagesUi16::positions(project);bool originalModified=project->projectOptionsWereModified(),committed=false;
 auto data=QetLanguagePositions21::capture(project,before);QetLanguagesUi16::scan(project,data);const QString lang=QetLanguages16::activeLanguage(data),id=QetLanguages16::effectiveId21(data,text->languageId16());auto e=QetLanguages16::entry(data,id);auto v=QetLanguages16::variant(data,id,lang);
 QDialog dialog(parent);dialog.setObjectName("translationEditor21");dialog.setWindowTitle(QObject::tr("Edit drawing text — %1").arg(lang));dialog.resize(650,700);auto *layout=new QVBoxLayout(&dialog);auto *badge=new QLabel(QObject::tr("Editing: %1 · Original language: %2").arg(lang,QetLanguages16::sourceLanguage(data)));badge->setObjectName("languageBadge21");layout->addWidget(badge);
 auto *reference=new QComboBox;reference->setObjectName("textReference21");reference->addItems(QetLanguages16::languageCodes(data));reference->setCurrentText(QetLanguages16::sourceLanguage(data));layout->addWidget(reference);auto *original=new QPlainTextEdit;original->setReadOnly(true);original->setMaximumHeight(100);layout->addWidget(original);
 auto updateReference=[&](){original->setPlainText(reference->currentText()==QetLanguages16::sourceLanguage(data)?e.value("source").toString():QetLanguages16::variant(data,id,reference->currentText()).value("text",e.value("source")).toString());};QObject::connect(reference,&QComboBox::currentTextChanged,&dialog,updateReference);updateReference();
 auto *translation=new QPlainTextEdit(v.value("text").toString());translation->setObjectName("translationText21");translation->setPlaceholderText(QObject::tr("Enter the complete %1 translation").arg(lang));layout->addWidget(translation,1);auto *copy=new QPushButton(QObject::tr("Copy reference → translation"));layout->addWidget(copy);QObject::connect(copy,&QPushButton::clicked,&dialog,[&](){translation->setPlainText(original->toPlainText());});
 auto *form=new QFormLayout;auto *width=new QDoubleSpinBox;width->setObjectName("translationWidth21");width->setRange(0,10000);width->setSpecialValueText(QObject::tr("Inherit / Auto"));width->setValue(v.value("width",0).toDouble());form->addRow(QObject::tr("Wrap width (drawing units)"),width);auto *lines=new QSpinBox;lines->setRange(0,1000);lines->setValue(v.value("maxLines",0).toInt());form->addRow(QObject::tr("Maximum lines (0 = unlimited)"),lines);
 auto *align=new QComboBox;align->addItem(QObject::tr("Inherit alignment"),0);align->addItem(QObject::tr("Left"),int(Qt::AlignLeft));align->addItem(QObject::tr("Centre"),int(Qt::AlignHCenter));align->addItem(QObject::tr("Right"),int(Qt::AlignRight));align->setCurrentIndex(qMax(0,align->findData(v.value("alignment",0))));form->addRow(QObject::tr("Alignment"),align);
 auto *anchor=new QComboBox;anchor->setObjectName("translationAnchor22");anchor->addItem(QObject::tr("Original text anchor"),0);anchor->addItem(QObject::tr("Keep left edge"),int(Qt::AlignLeft));anchor->addItem(QObject::tr("Keep centre"),int(Qt::AlignHCenter));anchor->addItem(QObject::tr("Keep right edge"),int(Qt::AlignRight));anchor->setCurrentIndex(qMax(0,anchor->findData(v.value("anchor22",0))));form->addRow(QObject::tr("Position anchor"),anchor);

 auto *fontOverride=new QCheckBox(QObject::tr("Use a font for this text and language"));fontOverride->setChecked(v.contains("font"));auto *font=new QPushButton;QFont chosen=text->font();if(v.contains("font"))chosen.fromString(v.value("font").toString());font->setText(chosen.family()+" "+QString::number(chosen.pointSizeF()));form->addRow(fontOverride,font);QObject::connect(font,&QPushButton::clicked,&dialog,[&](){bool ok;auto result=QFontDialog::getFont(&ok,chosen,&dialog);if(ok){chosen=result;fontOverride->setChecked(true);font->setText(chosen.family()+" "+QString::number(chosen.pointSizeF()));}});
 auto *x=new QDoubleSpinBox,*y=new QDoubleSpinBox;for(auto *spin:{x,y}){spin->setRange(-100000,100000);spin->setDecimals(2);}x->setObjectName("translationX21");y->setObjectName("translationY21");x->setValue(text->pos().x());y->setValue(text->pos().y());form->addRow(QObject::tr("X (relative to parent)"),x);form->addRow(QObject::tr("Y (relative to parent)"),y);auto *locked=new QCheckBox(QObject::tr("Lock this language's position"));locked->setChecked(v.value("locked").toBool());form->addRow(locked);layout->addLayout(form);bool positionChanged21=false;for(auto *spin:{x,y})QObject::connect(spin,QOverload<double>::of(&QDoubleSpinBox::valueChanged),&dialog,[&](double){positionChanged21=true;});
 auto *note=new QLabel(QObject::tr("Only this language is edited. To edit the original, switch the drawing language to %1 in Project languages. Automatic arrangement is a separate action.").arg(QetLanguages16::sourceLanguage(data)));note->setWordWrap(true);layout->addWidget(note);auto *preview=new QPushButton(QObject::tr("Preview translated text"));layout->addWidget(preview);auto *buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Apply|QDialogButtonBox::Cancel);layout->addWidget(buttons);
 auto read=[&](){auto es=data.value("entries").toMap();auto record=es.value(id).toMap();auto vs=record.value("variants").toMap();auto value=vs.value(lang).toMap();value["text"]=translation->toPlainText();value["stale"]=false;if(width->value()>0)value["width"]=width->value();else value.remove("width");value["maxLines"]=lines->value();if(anchor->currentData().toInt())value["anchor22"]=anchor->currentData();else value.remove("anchor22");if(align->currentData().toInt())value["alignment"]=align->currentData();else value.remove("alignment");if(fontOverride->isChecked())value["font"]=chosen.toString();else value.remove("font");if(positionChanged21){value["x"]=x->value();value["y"]=y->value();}value["locked"]=locked->isChecked();vs[lang]=value;record["variants"]=vs;es[id]=record;data["entries"]=es;};
 auto commit=[&](){read();data=QetLanguagesUi16::apply(project,data,false);auto afterPos=QetLanguagesUi16::positions(project);if(before!=data){text->diagram()->undoStack().push(new QetLanguagesUi16::Change(project,before,data,beforePos,afterPos));before=data;beforePos=afterPos;committed=true;}};
 QObject::connect(preview,&QPushButton::clicked,&dialog,[&](){read();data=QetLanguagesUi16::apply(project,data,false);});QObject::connect(buttons->button(QDialogButtonBox::Apply),&QPushButton::clicked,&dialog,commit);QObject::connect(buttons,&QDialogButtonBox::accepted,&dialog,[&](){commit();dialog.accept();});QObject::connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.exec();QetLanguagesUi16::apply(project,before,false);QetLanguagesUi16::restorePositions(beforePos);if(!committed)project->setModified(originalModified);
}
class Properties:public PropertiesEditorWidget{
 QPointer<DiagramTextItem> text;QLabel *badge;QPlainTextEdit *target,*source;QPushButton *edit;
 public:explicit Properties(DiagramTextItem *item,QWidget *parent=nullptr):PropertiesEditorWidget(parent){setObjectName("languageProperties21");auto *layout=new QVBoxLayout(this);badge=new QLabel;badge->setWordWrap(true);layout->addWidget(badge);target=new QPlainTextEdit;target->setObjectName("selectedTranslation21");target->setReadOnly(true);target->setMaximumHeight(110);layout->addWidget(target);edit=new QPushButton;layout->addWidget(edit);layout->addWidget(new QLabel(tr("Original / reference text")));source=new QPlainTextEdit;source->setReadOnly(true);source->setMaximumHeight(90);layout->addWidget(source);auto *hint=new QLabel(tr("Use the language editor for translation, font, wrapping and position. Original text and symbol information remain separate."));hint->setWordWrap(true);layout->addWidget(hint);layout->addStretch();QObject::connect(edit,&QPushButton::clicked,this,[this](){if(text){if(active(text))editText(text,this);else text->edit();}updateUi();});setText(item);}
 void setText(DiagramTextItem *item){if(text&&text->diagram())QObject::disconnect(text->diagram()->project(),nullptr,this,nullptr);text=item;if(item&&item->diagram())QObject::connect(item->diagram()->project(),&QETProject::languageDataChanged,this,[this](){updateUi();});updateUi();}
 void apply()override{}bool setLiveEdit(bool value)override{m_live_edit=value;return true;}
 protected:void updateUi()override{if(!text||!text->diagram())return;auto data=text->diagram()->project()->languageData();const auto id=QetLanguages16::effectiveId21(data,text->languageId16());auto e=QetLanguages16::entry(data,id);const QString lang=QetLanguages16::activeLanguage(data);badge->setText(tr("Drawing / editing language: %1").arg(lang));target->setPlainText(lang==QetLanguages16::sourceLanguage(data)?e.value("source",text->toPlainText()).toString():QetLanguages16::variant(data,id).value("text").toString());source->setPlainText(e.value("source",text->toPlainText()).toString());edit->setText(tr("Edit %1 text, font and layout…").arg(lang));edit->setEnabled(!text->diagram()->isReadOnly());}
};
